// A complete public App install or refusal is the timed operation. Setup,
// context derivation, verification, revocation and recycling are outside it.
use coaptic::storage::{DatagramIo, DatagramTransport};
use coaptic::{
    App, Endpoint,
    app::OscoreInstallError,
    message::OwnedToken,
    oscore::{BoundedSecurityContext, DeriveParams},
    resources,
};
use std::{hint::black_box, time::Instant};

const WIDTH: usize = 32;
const WARM: usize = 24;
const PEER: Endpoint = Endpoint::v4([192, 0, 2, 1], 5683);

struct Wire;
impl DatagramTransport for Wire {
    type Error = ();
}
impl DatagramIo for Wire {
    fn recv(&mut self, _: &mut [u8]) -> Result<Option<(usize, Endpoint)>, ()> {
        panic!("unexpected receive")
    }
    fn send(&mut self, _: Endpoint, _: &[u8]) -> Result<usize, ()> {
        panic!("unexpected send")
    }
}

fn material<K: OwnedToken>(kid: u8) -> BoundedSecurityContext<4, K> {
    BoundedSecurityContext::derive(DeriveParams {
        master_secret: &[kid; 16],
        master_salt: &[],
        sender_id: &[0],
        recipient_id: &[kid],
        id_context: &[],
    })
    .unwrap()
}

fn run<const A: usize>(case: &str, rounds: usize) {
    assert!((1..=64).contains(&A));
    let hole = match case {
        "first" => Some(0),
        "last" => Some(A - 1),
        "full" | "owner-conflict" | "kid-conflict" => None,
        _ => panic!("unknown case"),
    };
    let candidate_kid = if case == "kid-conflict" { A as u8 } else { 250 };
    let owner = if case == "owner-conflict" {
        [1; 32]
    } else {
        [250; 32]
    };
    let mut lanes = Vec::with_capacity(WIDTH);
    for _ in 0..WIDTH {
        let mut app = App::with_resources(resources::SmallDevice::new().associations::<A>())
            .deterministic_for_tests()
            .require_associations()
            .bind(Wire)
            .unwrap();
        let mut removed = None;
        for index in 0..A {
            let kid = (index + 1) as u8;
            let id = app
                .install_association(PEER, [kid; 32], 1, &mut Some(material(kid)))
                .unwrap();
            assert_eq!(app.association_at(index), Some(id));
            if Some(index) == hole {
                removed = Some(id);
            }
        }
        if let Some(id) = removed {
            app.remove_association(id).unwrap();
        }
        lanes.push((app, Some(material(candidate_kid))));
    }
    let mut outs = vec![None; WIDTH];
    let mut ns: u128 = 0;
    let mut meter_ns: u128 = 0;
    for round in 0..rounds + WARM {
        // Cost of two identical Instant samples, separately from each measured batch.
        // No subtraction from the raw elapsed time.
        let meter_start = Instant::now();
        let meter = meter_start.elapsed().as_nanos();
        let begin = Instant::now();
        for ((app, candidate), result) in black_box(&mut lanes).iter_mut().zip(&mut outs) {
            *result = Some(app.install_association(PEER, owner, 1, candidate));
        }
        black_box(&outs);
        let elapsed = begin.elapsed().as_nanos();
        if round >= WARM {
            ns += elapsed;
            meter_ns += meter;
        }
        for ((app, candidate), result) in lanes.iter_mut().zip(&mut outs) {
            let result = result.take().unwrap();
            if let Some(index) = hole {
                let installed = result.expect("vacancy accepted");
                assert!(candidate.is_none() && app.association_is_active(installed));
                assert_eq!(app.association_at(index), Some(installed));
                assert_eq!(installed.owner(), &owner);
                assert_eq!(installed.epoch(), 1);
                assert_eq!(installed.endpoint(), PEER);
                *candidate = Some(app.remove_association(installed).unwrap());
                assert!(app.association_at(index).is_none());
            } else {
                assert_eq!(
                    result,
                    Err(if case == "full" {
                        OscoreInstallError::Capacity
                    } else {
                        OscoreInstallError::Ambiguous
                    })
                );
                assert_eq!(app.association_at(0).unwrap().owner(), &[1; 32]);
                assert_eq!(app.association_at(A - 1).unwrap().owner(), &[A as u8; 32]);
            }
            assert_eq!(candidate.as_ref().unwrap().recipient_id(), &[candidate_kid]);
        }
    }
    println!("{A} {case} {} {ns} {meter_ns} {WIDTH}", WIDTH * rounds);
}

fn main() {
    let mut args = std::env::args().skip(1);
    let capacity = args.next().unwrap();
    let case = args.next().unwrap();
    let rounds: usize = args.next().unwrap().parse().unwrap();
    assert!(rounds > 0 && args.next().is_none());
    match capacity.as_str() {
        "1" => run::<1>(&case, rounds),
        "32" => run::<32>(&case, rounds),
        _ => panic!("unknown capacity"),
    }
}

