use coaptic::message::{OwnedToken, decode};
use coaptic::oscore::{BoundedSecurityContext, DeriveParams};
use coaptic::provisioning::{
    AdmissionLimits, AdmissionRegistry, AdmittedSession, CloudAdmission, CoapProvisioner,
    CredentialReference, Identity, PeerTrust, Status, TrustAnchor,
};
use coaptic::storage::{DatagramIo, DatagramTransport};
use coaptic::{App, Code, Endpoint, resources};
use std::{hint::black_box, time::Instant};

const WIDTH: usize = 16;
const WARM: usize = 4;
const SERVER: Endpoint = Endpoint::v4([192, 0, 2, 254], 5683);
const PEER: Endpoint = Endpoint::v4([192, 0, 2, 1], 49152);
#[derive(Default)]
struct Wire {
    response: Vec<u8>,
}
impl DatagramTransport for Wire {
    type Error = ();
}
impl DatagramIo for Wire {
    fn recv(&mut self, _: &mut [u8]) -> Result<Option<(usize, Endpoint)>, ()> {
        panic!("receive is caller-owned")
    }
    fn send(&mut self, _: Endpoint, bytes: &[u8]) -> Result<usize, ()> {
        self.response.clear();
        self.response.extend_from_slice(bytes);
        Ok(bytes.len())
    }
}
struct Registry(Option<PeerTrust>);
impl AdmissionRegistry for Registry {
    fn resolve(&self, reference: CredentialReference) -> Option<&PeerTrust> {
        self.0
            .as_ref()
            .filter(|t| t.checkpoint().peer().kid() == reference.kid())
    }
}
fn random(out: &mut [u8]) -> bool {
    getrandom::fill(out).is_ok()
}
fn identity(value: u8) -> Identity {
    let mut scalar = [0; 32];
    scalar[31] = value;
    Identity::from_private_key(scalar, value).unwrap()
}
fn material<K: OwnedToken>(kid: &[u8]) -> BoundedSecurityContext<4, K> {
    BoundedSecurityContext::derive(DeriveParams {
        master_secret: &[0x33; 16],
        master_salt: &[],
        sender_id: &[0],
        recipient_id: kid,
        id_context: &[],
    })
    .unwrap()
}
struct Staged<'a> {
    cloud: CloudAdmission<'a, 1, 1, 1, 1>,
    candidate: Option<AdmittedSession>,
    lease: coaptic::provisioning::Association,
}
fn fresh<'a>(server: &'a Identity, peer: &Identity, registry: &Registry) -> Staged<'a> {
    let mut cloud =
        CloudAdmission::<1, 1, 1, 1>::new(server, 0, AdmissionLimits::default(), random).unwrap();
    let mut client = CoapProvisioner::start(peer, server.peer(), SERVER, 0, random).unwrap();
    let mut c = Wire::default();
    let mut s = Wire::default();
    for (round, code) in [Code::UNAUTHORIZED, Code::CHANGED, Code::CHANGED]
        .into_iter()
        .enumerate()
    {
        client.flush(&mut c, 0).unwrap();
        let request = decode(&c.response).unwrap();
        let status = cloud
            .ingest(&c.response, PEER, 0, registry, random)
            .unwrap();
        assert_eq!(
            status,
            if round == 2 {
                Status::Complete
            } else {
                Status::Progress
            }
        );
        cloud.flush(&mut s, 0, registry).unwrap();
        let reply = decode(&s.response).unwrap();
        assert_eq!(reply.code(), code);
        assert_eq!(reply.message_id(), request.message_id());
        assert_eq!(reply.token().as_bytes(), request.token().as_bytes());
        client
            .ingest(&s.response, SERVER, 0, random, |p| {
                p == &server.peer().principal()
            })
            .unwrap();
    }
    let staged = cloud.take_session(0, registry).unwrap().unwrap();
    let client_session = client.take_session().unwrap();
    assert_eq!(client_session.principal(), &server.peer().principal());
    let lease = *staged.association();
    assert_eq!(lease.endpoint(), PEER);
    Staged {
        cloud,
        candidate: Some(staged),
        lease,
    }
}
fn run<const A: usize>(case: &str, rounds: usize) {
    let server = identity(71);
    let peer = identity(72);
    let registry = Registry(Some(
        PeerTrust::install(
            &server,
            peer.peer(),
            TrustAnchor::genesis([73; 32]).unwrap(),
            |_, _, _| Ok::<_, ()>(()),
        )
        .unwrap(),
    ));
    let unknown = Registry(None);
    let hole = match case {
        "first" => Some(0),
        "last" => Some(A - 1),
        "full" | "owner-conflict" | "kid-conflict" | "unauthorized" => None,
        _ => panic!(),
    };
    // Prepare every real successful handoff before the clock. Refusals preserve
    // the authenticated session, so repeat that same unchanged stage per lane.
    let bank_len = WIDTH * if hole.is_some() { rounds + WARM } else { 1 };
    let mut bank: Vec<_> = (0..bank_len)
        .map(|_| fresh(&server, &peer, &registry))
        .collect();
    let principle = peer.peer().principal();
    let mut lanes = Vec::with_capacity(WIDTH);
    for stage in &bank[..WIDTH] {
        let mut app = App::with_resources(resources::SmallDevice::new().associations::<A>())
            .deterministic_for_tests()
            .require_associations()
            .bind(Wire::default())
            .unwrap();
        let mut remove = None;
        for i in 0..A {
            let id = (i + 1) as u8;
            let owner = if case == "owner-conflict" && i == 0 {
                *principle.fingerprint()
            } else {
                [id; 32]
            };
            let fingerprint = [id];
            let local = stage.lease.local_connection_id();
            let recipient = if case == "kid-conflict" && i == A - 1 {
                local.as_bytes()
            } else {
                &fingerprint
            };
            // Occupied owners normally use a different port. The KID-conflict
            // row must share the full physical endpoint to test that refusal.
            let endpoint = if case == "kid-conflict" && i == A - 1 {
                PEER
            } else {
                SERVER
            };
            let result = app
                .install_association(endpoint, owner, 1, &mut Some(material(recipient)))
                .unwrap();
            assert_eq!(app.association_at(i), Some(result));
            if Some(i) == hole {
                remove = Some(result)
            }
        }
        if let Some(id) = remove {
            app.remove_association(id).unwrap();
        }
        lanes.push(app);
    }
    let chosen = if case == "unauthorized" {
        &unknown
    } else {
        &registry
    };
    let mut outs = vec![None; WIDTH];
    let mut expected = None;
    let mut ns = 0u128;
    let mut meter = 0u128;
    for batch in 0..rounds + WARM {
        let offset = if hole.is_some() { batch * WIDTH } else { 0 };
        let stages = &mut bank[offset..offset + WIDTH];
        let z = Instant::now();
        let boundary = z.elapsed().as_nanos();
        let begin = Instant::now();
        for ((app, stage), result) in black_box(&mut lanes)
            .iter_mut()
            .zip(stages.iter_mut())
            .zip(&mut outs)
        {
            *result = Some(AdmittedSession::install(
                &mut stage.candidate,
                app,
                chosen,
                1,
            ));
        }
        black_box(&outs);
        let delta = begin.elapsed().as_nanos();
        if batch >= WARM {
            ns += delta;
            meter += boundary;
        }
        for ((app, stage), r) in lanes.iter_mut().zip(stages.iter_mut()).zip(&mut outs) {
            let r = r.take().unwrap();
            if let Some(slot) = hole {
                let installed = r.unwrap();
                assert_eq!(installed.owner(), principle.fingerprint());
                assert_eq!(installed.endpoint(), PEER);
                assert_eq!(installed.epoch(), 1);
                assert!(stage.candidate.is_none());
                assert_eq!(app.association_at(slot), Some(installed));
                assert!(app.association_is_active(installed));
                app.remove_association(installed).unwrap();
                assert!(app.association_at(slot).is_none());
                assert!(stage.cloud.release(stage.lease));
            } else {
                let fail = r.unwrap_err();
                if let Some(e) = &expected {
                    assert_eq!(&fail, e)
                } else {
                    assert_eq!(
                        format!("{fail:?}"),
                        match case {
                            "full" => "App(Capacity)",
                            "unauthorized" => "Unauthorized",
                            _ => "App(Ambiguous)",
                        }
                    );
                    expected = Some(fail);
                }
                assert_eq!(
                    stage.candidate.as_ref().unwrap().association(),
                    &stage.lease
                );
                assert!(app.association_at(A - 1).is_some());
            }
        }
    }
    println!("{A} {case} {} {ns} {meter} {bank_len}", rounds * WIDTH);
}
fn main() {
    let mut args = std::env::args().skip(1);
    let a = args.next().unwrap();
    let case = args.next().unwrap();
    let rounds = args.next().unwrap().parse::<usize>().unwrap();
    match a.as_str() {
        "1" => run::<1>(&case, rounds),
        "32" => run::<32>(&case, rounds),
        _ => panic!(),
    };
}
